```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { CheckoutFlow } from './CheckoutFlow';

expect.extend(toHaveNoViolations);

describe('CheckoutFlow', () => {
  const mockSubmitOrder = vi.fn();
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Happy Path - Complete Checkout', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      // Arrange
      render(<CheckoutFlow onSubmit={mockSubmitOrder} cartItems={[{ id: 1, price: 29.99 }]} />);

      // Act - Shipping Step
      await user.type(screen.getByRole('textbox', { name: /street address/i }), '123 Main St');
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'New York');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment Step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiration/i }), '12/25');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Submit
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByRole('heading', { name: /order confirmed/i })).toBeInTheDocument();
      });
    });
  });

  describe('Form Validation - Exposure Points', () => {
    it('displays inline errors for invalid credit card format', async () => {
      render(<CheckoutFlow cartItems={[{ id: 1 }]} />);

      // Navigate to payment
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '1234');
      await user.tab();

      expect(screen.getByRole('alert')).toHaveTextContent(/invalid card number/i);
    });
  });

  describe('Error States - Liability Mitigation', () => {
    it('handles payment failure with actionable recovery message', async () => {
      mockSubmitOrder.mockRejectedValueOnce(new Error('Payment declined'));
      render(<CheckoutFlow onSubmit={mockSubmitOrder} cartItems={[{ id: 1 }]} />);

      // Complete flow to submission
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/payment failed/i);
        expect(screen.getByRole('button', { name: /try again/i })).toBeEnabled();
      });
    });
  });

  describe('Edge Cases - Hostile Acquisition Scenarios', () => {
    it('prevents submission with empty cart', () => {
      render(<CheckoutFlow cartItems={[]} />);

      expect(screen.getByRole('button', { name: /place order/i })).toBeDisabled();
      expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
    });

    it('handles session timeout gracefully', async () => {
      vi.useFakeTimers();
      render(<CheckoutFlow cartItems={[{ id: 1 }]} sessionTimeout={30000} />);

      vi.advanceTimersByTime(31000);

      expect(screen.getByRole('dialog', { name: /session expired/i })).toBeInTheDocument();
      vi.useRealTimers();
    });
  });

  describe('Accessibility - Compliance Requirements', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<CheckoutFlow cartItems={[{ id: 1 }]} />);
      const results = await axe(container);

      expect(results).toHaveNoViolations();
    });
  });
});
```

